def pick(v, i): return v[i] if isinstance(v, tuple) else v
out = {}
for g, (P, col, dbt, dti, keep, ext, atk, sup, hyp) in G.items():
    for i, st in enumerate(['bt', 'ti']):
        desc = (dbt, dti)[i]; D = desc[0].upper() + desc[1:]
        noextra = '' if g in ('lucifer',) else 'No wings. '
        idle = IDLE.format(extra=pick(ext, i), keep=pick(keep, i), **P)
        out[f'{g}_{st}_idle'] = CAM + f"{D} keeps the same size and stays on the same spot. " + idle
        for slot, txt in (('atk', atk), ('sup', sup), ('hyp', hyp)):
            stay = 'and stays on the same spot.' if g == 'quetzalcoatl' and st == 'ti' else 'feet planted on the same spot.'
            out[f'{g}_{st}_{slot}'] = CAM + f"{D} keeps the same size, {stay} " + pick(txt, i) + END_ACT.format(col=col + ' effects', noextra=noextra)
json.dump(out, open('/home/claude/kl/b3/p6.json', 'w'), indent=1, ensure_ascii=False)
print(len(out), max(len(v) for v in out.values()))
